(() => {
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap'), mctx = mini.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const W = 3000, H = 2300, TAU = Math.PI * 2;
  let vw = 1, vh = 1, dpr = 1, last = 0, running = false, paused = false, mapBig = false, gameOver = false;
  const keys = new Set(), mouse = {x: 0, y: 0, down: false};
  const cam = {x: 0, y: 0};
  const player = {x: 520, y: 490, angle: 0, health: 100, armor: 40, speed: 0, inCar: null, ammo: 12, weapon: 1, wanted: 0, shootCD: 0, invuln: 0};
  const stageNames = ['THE RETURN','THREE OLD STORIES','THE STATION','NO WAY BACK','AFTER THE TIDE'];
  let stage = 0, clues = [false,false,false], policeDone = false, toastTimer = 0, dialogue = null, dialogueStep = 0, gameTime = 21.23;
  const places = [
    {x:710,y:430,name:'SOUTH MARKET',district:'OLD HARBOR',title:'A familiar face',initial:'R',role:'SOUTH MARKET',lines:['“Marcus Vale? I thought you were a ghost. Your brother came through here a few months back. He was asking around about the old crew.”','“The Breakwater boys were running a job with him. They’ll know more than I do. Try their garage on the south side.”'],type:'clue',index:0},
    {x:1660,y:510,name:'BREAKWATER GARAGE',district:'IRON QUARTER',title:'Rook',initial:'R',role:'BREAKWATER CREW',lines:['“Your brother? He helped us move a shipment. Never took a cut. We didn’t touch him, Vale.”','“He said he was trying to get close to the Crown. Said it was the only way to reach someone inside.”'],type:'clue',index:1},
    {x:1940,y:1500,name:'THE SALT YARD',district:'SALT YARD',title:'Mara Venn',initial:'M',role:'SALT YARD COLLECTIVE',lines:['“He was like family. We ran half a dozen jobs together and he never once sold us out.”','“If someone hurt him, we’ll help you find them. But you should talk to Detective Sato first. She left a message at the precinct.”'],type:'clue',index:2},
    {x:520,y:1700,name:'HARBOR PRECINCT',district:'CIVIC DISTRICT',title:'Detective Sato',initial:'S',role:'HARBOR CITY POLICE',lines:['“I’m sorry, Marcus. The case went cold, but the evidence didn’t. Your brother was killed by his own crew — the Crown.”','“He was going to turn state’s evidence. They found out. I can’t give you a badge, but I can give you the truth. Make your choice.”'],type:'police'},
    {x:2360,y:1900,name:'CROWN WAREHOUSE',district:'THE BREAKWATER',title:'The Crown',initial:'V',role:'CROWN SYNDICATE',lines:['“You came all this way for him?” Vale’s voice carries across the loading bay. “He was family. He chose to betray us.”','There is no answer left to hear. The harbor wind takes the last of the noise.'],type:'final'}
  ];
  const buildings = [], cars = [], enemies = [], civilians = [], bullets = [], particles = [];
  const colors = ['#34403d','#3b4340','#4a4940','#33403f','#514b42','#394541','#454640'];
  let seed = 98423; const rand = () => {seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
  // City's blocks, courtyards, roofs and back alleys are generated from a stable layout.
  for(let gx=0;gx<5;gx++) for(let gy=0;gy<4;gy++) {
    const bx=150+gx*560, by=130+gy*540;
    for(let i=0;i<5;i++) {
      const bw=75+rand()*105, bh=70+rand()*125, x=bx+(i%3)*145+rand()*16, y=by+Math.floor(i/3)*205+rand()*16;
      if(x+bw>W-160 || y+bh>H-120 || (x>2250 && gy>2)) continue;
      buildings.push({x,y,w:bw,h:bh,c:colors[Math.floor(rand()*colors.length)],accent:['#c9855d','#829276','#d1ad71','#648c88'][Math.floor(rand()*4)],seed:rand(),height:10+rand()*14});
    }
  }
  const carSpecs=[['COUPE','#bf744f'],['SEDAN','#728376'],['RALLY','#c4a767'],['VAN','#7c8580'],['SPEEDBOAT','#d8c99a']];
  [[620,650,0,0],[1040,480,Math.PI/2,1],[1380,1050,0,2],[450,1320,Math.PI/2,3],[2050,900,Math.PI/2,1],[2210,1720,0,0],[1940,1860,Math.PI/2,2],[470,1850,0,4],[2520,1330,Math.PI/2,4]].forEach(([x,y,a,s])=>cars.push({x,y,angle:a,spec:s,color:carSpecs[s][1],occupied:false,speed:0,parked:true}));
  const addEnemy=(x,y,boss=false)=>enemies.push({x,y,angle:0,hp:boss?5:2,boss,alert:false,attack:0,dead:false});
  [[2210,1850,false],[2270,1960,false],[2470,1800,false],[2550,1900,false],[2290,2040,false]].forEach(p=>addEnemy(...p));
  [[720,570],[1170,870],[1660,650],[1900,1130],[1250,1600],[910,1870],[1780,1940],[620,1140],[1460,330],[2080,660],[520,770],[1530,1740]].forEach(([x,y],i)=>civilians.push({x,y,phase:rand()*8,color:['#b79c72','#93a49a','#b7765d','#828d9d'][i%4]}));
  addEnemy(2390,1880,true);
  const setMission=()=>{
    const title=$('mission-title'), copy=$('mission-copy'), kick=$('mission-kicker'), rows=$('objectives');
    $('chapter-label').textContent=`CHAPTER 0${Math.min(stage+1,5)}  /  ${stageNames[stage]||'THE RETURN'}`; rows.innerHTML='';
    const obj=(text,done=false,active=false)=>{const d=document.createElement('div');d.className='objective'+(done?' done':'')+(active?' active':'');d.textContent=text;rows.appendChild(d)};
    if(stage===0){kick.textContent='YOUR STORY';title.innerHTML='The City<br/>Didn’t Wait.';copy.textContent='Eighteen years away. One old friend missing. Find out what the harbor remembers.';obj('Ask around South Market',false,true);}
    else if(stage===1){kick.textContent='FOLLOW THE THREAD';title.innerHTML='Three Old<br/>Stories.';copy.textContent='Your brother left a trail across the city. Every crew remembers him differently.';places.slice(0,3).forEach((p,i)=>obj(`Speak with ${['South Market','Breakwater','the Salt Yard'][i]}`,clues[i],!clues[i]));}
    else if(stage===2){kick.textContent='NEW EVIDENCE';title.innerHTML='A Call From<br/>The Station.';copy.textContent='Detective Sato says she can tell you what happened. Head to Harbor Precinct.';obj('Meet Detective Sato at the precinct',false,true);}
    else if(stage===3){kick.textContent='THE LAST LEAD';title.innerHTML='Blood Runs<br/>Deeper.';copy.textContent='The Crown killed your brother to keep him quiet. The other crews are ready to stand with you.';obj('Reach the Crown warehouse',false,true);obj('Take down the Crown lieutenant');}
    else{kick.textContent='HARBOR CITY';title.innerHTML='The Tide<br/>Turned.';copy.textContent='The truth is out. For the first time in eighteen years, Marcus knows where home is.';obj('Case closed — explore the city',true,true);}
    $('progress-label').textContent=`0${Math.min(stage+1,4)} — 04`; $('progress-fill').style.width=`${Math.min(100,stage*25)}%`;
  };
  function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');toastTimer=3.2;}
  function resize(){dpr=Math.min(devicePixelRatio||1,1.7);vw=innerWidth;vh=innerHeight;canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
  addEventListener('resize',resize); resize();
  const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function activePlace(){if(stage===0)return places[0];if(stage===1)return places.find(p=>p.type==='clue'&&!clues[p.index])||places[3];if(stage===2)return places[3];if(stage===3)return places[4];return null;}
  function worldMouse(){return{x:mouse.x+cam.x,y:mouse.y+cam.y};}
  function beginDialogue(p){dialogue=p;dialogueStep=0;showLine();}
  function showLine(){if(!dialogue)return; $('dialogue').classList.remove('hidden');$('dialogue-initial').textContent=dialogue.initial;$('dialogue-role').textContent=dialogue.role;$('dialogue-name').textContent=dialogue.title;$('dialogue-line').textContent=dialogue.lines[dialogueStep]||'';}
  function advanceDialogue(){if(!dialogue)return;dialogueStep++;if(dialogueStep<dialogue.lines.length){showLine();return;}const p=dialogue;dialogue=null;$('dialogue').classList.add('hidden');
    if(p.type==='clue'){clues[p.index]=true;if(clues.every(Boolean)){stage=2;toast('Three crews. Three stories. A new lead at Harbor Precinct.');}else{stage=1;toast('Lead added to your case file.');}setMission();}
    else if(p.type==='police'){policeDone=true;stage=3;enemies.forEach(e=>{e.alert=true});toast('THE CROWN WAREHOUSE — other crews are moving in with you.');setMission();}
    else if(p.type==='final'){stage=4;gameOver=true;$('ending-screen').classList.remove('hidden');setMission();}
  }
  function interact(){if(dialogue){advanceDialogue();return;}const p=activePlace();if(p&&dist(player,p)<112){if(p.type==='final'&&enemies.some(e=>!e.dead&&e.boss)){toast('The lieutenant is still standing. Clear the yard first.');return;}beginDialogue(p);return;}
    if(player.inCar){const car=player.inCar;player.inCar=null;car.occupied=false;player.x=car.x+Math.cos(car.angle+Math.PI/2)*34;player.y=car.y+Math.sin(car.angle+Math.PI/2)*34;player.angle=car.angle;toast('On foot.');return;}
    const car=cars.find(c=>!c.occupied&&Math.hypot(c.x-player.x,c.y-player.y)<75);if(car){player.inCar=car;car.occupied=true;toast(`${carSpecs[car.spec][0]} — drive safe.`);return;}
    toast('Nothing to interact with here.');
  }
  function fire(){if(!running||paused||dialogue||player.inCar)return;if(player.shootCD>0)return;if(player.ammo<=0){toast('Magazine empty — press R to reload.');player.shootCD=.3;return;}player.ammo--;player.shootCD=.22;const aim=worldMouse();const a=Math.atan2(aim.y-player.y,aim.x-player.x);player.angle=a;const sx=player.x+Math.cos(a)*20,sy=player.y+Math.sin(a)*20;bullets.push({x:sx,y:sy,vx:Math.cos(a)*650,vy:Math.sin(a)*650,life:.8});for(let i=0;i<4;i++)particles.push({x:sx,y:sy,vx:Math.cos(a)+(rand()-.5),vy:Math.sin(a)+(rand()-.5),life:.2,color:'#ffca77',size:2});
    const target=enemies.filter(e=>!e.dead).sort((a,b)=>dist(a,{x:sx,y:sy})-dist(b,{x:sx,y:sy}))[0];if(target&&dist(target,{x:sx,y:sy})<460){target.alert=true;if(Math.abs(Math.atan2(target.y-sy,target.x-sx)-a)<.20||dist(target,{x:sx, y:sy})<36){target.hp--;if(target.hp<=0){target.dead=true;for(let i=0;i<10;i++)particles.push({x:target.x,y:target.y,vx:(rand()-.5)*100,vy:(rand()-.5)*100,life:.6,color:'#d68062',size:3});if(target.boss){toast('The Crown lieutenant is down. The yard is clear.');}else toast('Hostile down. Keep moving.');}}}
    if(player.wanted<3)player.wanted++;$('heat-label').textContent=player.wanted?'WANTED '+player.wanted+'★':'CLEAN';
  }
  function update(dt){if(!running||paused)return;gameTime=(gameTime+dt*.007)%24;player.shootCD=Math.max(0,player.shootCD-dt);player.invuln=Math.max(0,player.invuln-dt);toastTimer-=dt;if(toastTimer<=0)$('toast').classList.add('hidden');
    const mvx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),mvy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);const len=Math.hypot(mvx,mvy)||1;
    if(player.inCar){const car=player.inCar;const throttle=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0);const steer=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);car.speed+=(throttle*320-car.speed*1.35)*dt;car.speed=Math.max(-120,Math.min(310,car.speed));car.angle+=steer*dt*(.8+Math.abs(car.speed)/130);car.x=Math.max(40,Math.min(W-40,car.x+Math.cos(car.angle)*car.speed*dt));car.y=Math.max(40,Math.min(H-40,car.y+Math.sin(car.angle)*car.speed*dt));player.x=car.x;player.y=car.y;player.angle=car.angle;}
    else if(!dialogue){const speed=keys.has('shift')?250:155;player.x=Math.max(32,Math.min(W-32,player.x+mvx/len*speed*dt));player.y=Math.max(32,Math.min(H-32,player.y+mvy/len*speed*dt));if(mvx||mvy)player.angle=Math.atan2(mvy,mvx);}
    if(!player.inCar&&!dialogue){const a=worldMouse();if(Math.hypot(mouse.x-vw/2,mouse.y-vh/2)>20)player.angle=Math.atan2(a.y-player.y,a.x-player.x);}
    for(const e of enemies){if(e.dead)continue;const d=dist(e,player);if(e.alert||d<260){e.alert=true;if(d>35){const a=Math.atan2(player.y-e.y,player.x-e.x);e.angle=a;e.x+=Math.cos(a)*56*dt;e.y+=Math.sin(a)*56*dt;}else{e.attack-=dt;if(e.attack<=0){e.attack=1.1;if(player.armor>0)player.armor=Math.max(0,player.armor-8);else player.health=Math.max(0,player.health-12);player.invuln=.3;updateVitals();}}}}
    bullets.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt});for(let i=bullets.length-1;i>=0;i--)if(bullets[i].life<=0)bullets.splice(i,1);
    particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt});for(let i=particles.length-1;i>=0;i--)if(particles[i].life<=0)particles.splice(i,1);
    if(player.health<=0){player.health=100;player.armor=25;player.x=520;player.y=490;player.inCar=null;enemies.forEach(e=>{if(!e.dead)e.alert=false});toast('You made it back to the market. Watch your step.');updateVitals();}
    cam.x=Math.max(0,Math.min(W-vw,player.x-vw/2));cam.y=Math.max(0,Math.min(H-vh,player.y-vh/2));
    const place=activePlace(),near=place&&dist(player,place)<112;$('interaction').classList.toggle('hidden',!near||!!dialogue);if(near){$('interaction-text').textContent=place.type==='final'?'Approach the lieutenant':'Talk to '+place.title;}if(!near&&!player.inCar){const car=cars.find(c=>!c.occupied&&dist(player,c)<75);if(car){$('interaction').classList.remove('hidden');$('interaction-text').textContent=`Enter ${carSpecs[car.spec][0]}`;}}
    $('clock').textContent=`${String(Math.floor(gameTime)%24).padStart(2,'0')}:${String(Math.floor(gameTime*60%60)).padStart(2,'0')}`;const loc=places.reduce((a,b)=>dist(player,a)<dist(player,b)?a:b);$('location-name').textContent=loc.name;$('map-district').textContent=loc.district;$('crosshair').classList.toggle('hidden',!mouse.down);
  }
  function updateVitals(){$('health-fill').style.width=player.health+'%';$('health-fill').style.background=player.health<30?'#ec795e':'var(--acid)';$('health-text').textContent=player.health;$('armor-text').textContent=player.armor;}

function drawWorld(){
  ctx.fillStyle='#28352e';ctx.fillRect(0,0,W,H);
  // Distinct blocks of scrub, pavement and planted medians soften the grid.
  for(let x=0;x<W;x+=112)for(let y=0;y<H;y+=112){const n=((x*13+y*7)%29);ctx.fillStyle=n<8?'#2b3931':n<17?'#29362f':'#2d3932';ctx.fillRect(x+2,y+2,108,108);if(n<5){ctx.fillStyle='rgba(128,142,94,.12)';ctx.beginPath();ctx.arc(x+37,y+68,19,0,TAU);ctx.fill();}}
  // Harbor inlet and seawall.
  ctx.fillStyle='#1d4245';ctx.beginPath();ctx.moveTo(2620,0);ctx.lineTo(W,0);ctx.lineTo(W,H);ctx.lineTo(2620,H);ctx.lineTo(2540,2040);ctx.lineTo(2630,1760);ctx.lineTo(2570,1440);ctx.lineTo(2640,1120);ctx.lineTo(2560,820);ctx.lineTo(2630,520);ctx.closePath();ctx.fill();
  ctx.fillStyle='rgba(88,157,150,.13)';for(let i=0;i<42;i++){let x=2640+(i*91%330),y=(i*167)%H;ctx.fillRect(x,y,25+(i%6)*12,1);}
  ctx.strokeStyle='#76847c';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(2600,0);ctx.lineTo(2600,H);ctx.stroke();ctx.strokeStyle='rgba(222,212,169,.35)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(2609,0);ctx.lineTo(2609,H);ctx.stroke();
  // Roads.
  ctx.lineCap='butt';for(let x=300;x<W;x+=560){ctx.fillStyle='#30393a';ctx.fillRect(x-31,0,62,H);ctx.fillStyle='rgba(12,18,19,.32)';ctx.fillRect(x-35,0,4,H);ctx.fillRect(x+31,0,4,H);ctx.strokeStyle='rgba(221,204,147,.42)';ctx.lineWidth=1;ctx.setLineDash([19,17]);ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='rgba(224,225,199,.55)';for(let y=130;y<H;y+=540){ctx.fillRect(x-20,y,3,14);ctx.fillRect(x+17,y,3,14);}}
  for(let y=330;y<H;y+=540){ctx.fillStyle='#30393a';ctx.fillRect(0,y-30,W,60);ctx.fillStyle='rgba(12,18,19,.3)';ctx.fillRect(0,y-34,W,4);ctx.fillRect(0,y+30,W,4);ctx.strokeStyle='rgba(221,204,147,.4)';ctx.lineWidth=1;ctx.setLineDash([19,17]);ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.setLineDash([]);for(let x=90;x<W;x+=560){ctx.fillStyle='rgba(224,225,199,.48)';ctx.fillRect(x,y-20,14,3);ctx.fillRect(x,y+17,14,3);}}
  // Alleys, lot dividers, and curb details.
  ctx.strokeStyle='rgba(185,196,171,.13)';ctx.lineWidth=1;for(let x=20;x<W;x+=560){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=50;y<H;y+=540){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
  // Loading piers and container stacks.
  ctx.fillStyle='#56625b';ctx.fillRect(2680,380,270,112);ctx.fillRect(2690,1040,230,130);ctx.fillRect(2680,1770,280,112);ctx.fillStyle='#8c6750';for(let i=0;i<5;i++){ctx.fillRect(2700+i*48,397,40,74);ctx.fillStyle=i%2?'#627c70':'#a87958';}ctx.fillStyle='#607c70';ctx.fillRect(2710,1060,92,90);ctx.fillStyle='#967252';ctx.fillRect(2813,1060,89,90);
  for(const b of buildings)drawBuilding(b);
  drawStreetProps();
}
function drawBuilding(b){const x=b.x,y=b.y,w=b.w,h=b.h;ctx.fillStyle='rgba(0,0,0,.32)';ctx.fillRect(x+8,y+12,w,h);ctx.fillStyle='#202a28';ctx.fillRect(x-4,y+h-5,w+8,8);ctx.fillStyle=b.c;ctx.fillRect(x,y,w,h);ctx.fillStyle='rgba(255,255,255,.055)';ctx.fillRect(x+2,y+2,w-4,4);ctx.fillStyle='rgba(8,14,14,.32)';ctx.fillRect(x+w-7,y+6,7,h-6);ctx.fillStyle=b.accent;ctx.fillRect(x+8,y+8,Math.min(w-16,26),3);ctx.fillStyle='rgba(171,190,166,.14)';for(let wx=x+13;wx<x+w-9;wx+=21){ctx.fillRect(wx,y+13,7,5);if(b.h>95)ctx.fillRect(wx,y+28,7,5);}if(b.seed>.48){ctx.strokeStyle='rgba(210,218,191,.18)';ctx.lineWidth=1;ctx.strokeRect(x+w*.28,y+h*.34,w*.42,h*.32);ctx.fillStyle='rgba(9,15,14,.13)';ctx.fillRect(x+w*.33,y+h*.4,w*.3,h*.2);}if(b.seed>.72){ctx.fillStyle='#5e7066';ctx.fillRect(x+w*.63,y+h*.16,15,10);ctx.fillStyle='#82755e';ctx.fillRect(x+w*.18,y+h*.72,19,8);}}
function drawStreetProps(){
  for(let x=100;x<W;x+=560)for(let y=95;y<H;y+=540){ctx.fillStyle='rgba(232,212,152,.72)';ctx.fillRect(x,y,3,3);ctx.fillRect(x+42,y+9,3,3);ctx.fillStyle='#4b5a4f';ctx.beginPath();ctx.arc(x+70,y+58,12,0,TAU);ctx.fill();ctx.fillStyle='#768266';ctx.beginPath();ctx.arc(x+67,y+54,9,0,TAU);ctx.fill();ctx.fillStyle='#514d40';ctx.fillRect(x+66,y+61,4,9);}
  // Crosswalks make intersections legible at a glance.
  for(let x=300;x<W;x+=560)for(let y=330;y<H;y+=540){ctx.fillStyle='rgba(208,215,194,.37)';for(let i=-3;i<=3;i++)ctx.fillRect(x+i*7,y-42,3,10);for(let i=-3;i<=3;i++)ctx.fillRect(x+i*7,y+32,3,10);}
}
function drawPerson(x,y,angle,color,kind='civilian',pulse=0){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle='rgba(0,0,0,.33)';ctx.beginPath();ctx.ellipse(1,7,8,4,0,0,TAU);ctx.fill();if(kind==='player'){ctx.fillStyle='#252d2a';ctx.beginPath();ctx.ellipse(0,0,8,11,0,0,TAU);ctx.fill();ctx.fillStyle='#ce9b72';ctx.beginPath();ctx.arc(0,-5,5,0,TAU);ctx.fill();ctx.fillStyle='#3d5a50';ctx.fillRect(-6,-1,12,8);ctx.fillStyle='#d5cfaa';ctx.fillRect(2,-2,7,2);ctx.strokeStyle='#e7e8d2';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(6,0);ctx.lineTo(17,0);ctx.stroke();}else if(kind==='enemy'){ctx.fillStyle=pulse?'#d59063':'#734b42';ctx.beginPath();ctx.ellipse(0,0,8,10,0,0,TAU);ctx.fill();ctx.fillStyle='#d1a183';ctx.beginPath();ctx.arc(0,-5,4,0,TAU);ctx.fill();ctx.fillStyle='#262322';ctx.fillRect(3,-1,12,3);ctx.fillStyle='#f0a27d';ctx.fillRect(10,-2,4,1);}else{ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,0,7,9,0,0,TAU);ctx.fill();ctx.fillStyle='#cfaa86';ctx.beginPath();ctx.arc(0,-5,4,0,TAU);ctx.fill();}ctx.restore();}
function drawCar(car){ctx.save();ctx.translate(car.x,car.y);ctx.rotate(car.angle);const boat=car.spec===4;ctx.fillStyle='rgba(0,0,0,.37)';ctx.beginPath();ctx.ellipse(2,5,boat?25:25,boat?11:14,0,0,TAU);ctx.fill();ctx.fillStyle=car.color;ctx.beginPath();if(boat){ctx.moveTo(-26,-8);ctx.lineTo(17,-10);ctx.lineTo(27,0);ctx.lineTo(17,10);ctx.lineTo(-26,8);ctx.closePath();}else{ctx.roundRect(-24,-11,48,22,6);}ctx.fill();ctx.fillStyle=boat?'#263c3c':'#283735';ctx.beginPath();if(!boat)ctx.roundRect(-9,-8,19,16,4);else ctx.ellipse(2,0,8,5,0,0,TAU);ctx.fill();ctx.fillStyle='rgba(190,219,207,.32)';if(!boat){ctx.fillRect(-7,-7,7,14);ctx.fillRect(2,-7,6,14);}ctx.fillStyle='#ecd8a1';ctx.fillRect(19,-8,3,4);ctx.fillRect(19,4,3,4);ctx.fillStyle='#d56e54';ctx.fillRect(-23,-8,3,4);ctx.fillRect(-23,4,3,4);ctx.fillStyle='#141a19';if(!boat){ctx.fillRect(-15,-12,9,3);ctx.fillRect(8,-12,9,3);ctx.fillRect(-15,9,9,3);ctx.fillRect(8,9,9,3);}ctx.restore();}
function drawMarker(p){const pulse=.5+.5*Math.sin(performance.now()/390);ctx.save();ctx.translate(p.x,p.y);ctx.strokeStyle=`rgba(215,255,112,${.35+pulse*.45})`;ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,18+pulse*5,0,TAU);ctx.stroke();ctx.fillStyle='rgba(215,255,112,.16)';ctx.beginPath();ctx.arc(0,0,14,0,TAU);ctx.fill();ctx.fillStyle='#d7ff70';ctx.beginPath();ctx.arc(0,-1,5,0,TAU);ctx.fill();ctx.fillStyle='rgba(12,19,20,.85)';ctx.fillRect(-29,-35,58,14);ctx.fillStyle='#e4ebdc';ctx.font='8px "DM Mono",monospace';ctx.textAlign='center';ctx.fillText(p.name,0,-25);ctx.restore();}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,vw,vh);ctx.save();ctx.translate(-cam.x,-cam.y);drawWorld();
  const active=activePlace();if(active)drawMarker(active);
  for(const car of cars)drawCar(car);
  for(const c of civilians){const pulse=Math.sin(performance.now()/500+c.phase);drawPerson(c.x+Math.sin(performance.now()/2000+c.phase)*6,c.y+Math.cos(performance.now()/1800+c.phase)*5,pulse*.12,c.color);}
  for(const e of enemies){if(e.dead)continue;drawPerson(e.x,e.y,e.angle,'#a46753','enemy',e.boss);if(e.boss){ctx.fillStyle='#e8dfc7';ctx.font='9px "DM Mono",monospace';ctx.textAlign='center';ctx.fillText('CROWN LIEUTENANT',e.x,e.y-22);}}
  for(const b of bullets){ctx.fillStyle='#ffd27e';ctx.beginPath();ctx.arc(b.x,b.y,2.4,0,TAU);ctx.fill();}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life*2);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);ctx.globalAlpha=1;}
  if(player.inCar)drawCar(player.inCar);else drawPerson(player.x,player.y,player.angle,'#547567','player');ctx.restore();drawMinimap();
  if(player.inCar){$('weapon-name').textContent=carSpecs[player.inCar.spec][0];$('weapon-icon').textContent=player.inCar.spec===4?'⌁':'▰';}else{$('weapon-name').textContent=player.weapon===1?'SERVICE PISTOL':'COMPACT SMG';$('weapon-icon').textContent=player.weapon===1?'⌁':'⌖';}
  $('ammo-count').textContent=player.weapon===1?player.ammo:Math.min(30,player.ammo*2);}

