  function drawMinimap(){const mw=mini.width,mh=mini.height;mctx.clearRect(0,0,mw,mh);mctx.fillStyle='#28352e';mctx.fillRect(0,0,mw,mh);mctx.fillStyle='#1b4144';mctx.beginPath();mctx.moveTo(mw*.87,0);mctx.lineTo(mw,0);mctx.lineTo(mw,mh);mctx.lineTo(mw*.87,mh);mctx.lineTo(mw*.85,mh*.75);mctx.lineTo(mw*.88,mh*.5);mctx.closePath();mctx.fill();for(let x=300;x<W;x+=560){mctx.fillStyle='#41494a';mctx.fillRect(x/W*mw-1,0,3,mh);}for(let y=330;y<H;y+=540){mctx.fillStyle='#41494a';mctx.fillRect(0,y/H*mh,mw,3);}for(const b of buildings){mctx.fillStyle='#485149';mctx.fillRect(b.x/W*mw,b.y/H*mh,Math.max(1,b.w/W*mw),Math.max(1,b.h/H*mh));}for(const c of cars){mctx.fillStyle=c.spec===4?'#d7c78c':'#b9b8a0';mctx.fillRect(c.x/W*mw-1,c.y/H*mh-1,3,2);}const p=activePlace();if(p){mctx.fillStyle='#d7ff70';mctx.beginPath();mctx.arc(p.x/W*mw,p.y/H*mh,3.2,0,TAU);mctx.fill();}mctx.fillStyle='#ee8f6b';for(const e of enemies)if(!e.dead)mctx.fillRect(e.x/W*mw-1,e.y/H*mh-1,3,3);mctx.fillStyle='#faf0d0';mctx.beginPath();mctx.arc(player.x/W*mw,player.y/H*mh,3.3,0,TAU);mctx.fill();mctx.strokeStyle='rgba(215,255,112,.65)';mctx.lineWidth=1;mctx.beginPath();mctx.moveTo(player.x/W*mw,player.y/H*mh);mctx.lineTo(player.x/W*mw+Math.cos(player.angle)*7,player.y/H*mh+Math.sin(player.angle)*7);mctx.stroke();}
  function loop(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(loop);}
  requestAnimationFrame(loop);
  $('start-button').addEventListener('click',()=>{$('start-screen').classList.add('hidden');running=true;toast('Welcome home, Marcus. Start at South Market.');});
  $('resume-button').addEventListener('click',()=>{paused=false;$('pause-screen').classList.add('hidden');});
  $('ending-button').addEventListener('click',()=>{$('ending-screen').classList.add('hidden');});
  $('dialogue-next').addEventListener('click',advanceDialogue);
  $('map-toggle').addEventListener('click',()=>{mapBig=!mapBig;document.body.classList.toggle('map-large',mapBig);});
  addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'||k==='p'){if(!running)return;paused=!paused;$('pause-screen').classList.toggle('hidden',!paused);return;}if(k==='m'){mapBig=!mapBig;document.body.classList.toggle('map-large',mapBig);return;}if(k==='e'){interact();return;}if(k==='r'){player.ammo=12;toast('Magazine reloaded.');return;}if(k==='1'||k==='2'){player.weapon=Number(k);player.ammo=12;return;}keys.add(k);});
  addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top;});
  canvas.addEventListener('mousedown',e=>{if(e.button===0){mouse.down=true;fire();}});addEventListener('mouseup',()=>mouse.down=false);
  canvas.addEventListener('contextmenu',e=>e.preventDefault());
  const stick=$('touch-stick'), knob=stick.querySelector('i');let stickPointer=null;
  stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e);});
  stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e);});
  function moveStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=31,scale=len>max?max/len:1;knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;for(const k of ['w','a','s','d'])keys.delete(k);if(Math.abs(dx)>12)keys.add(dx>0?'d':'a');if(Math.abs(dy)>12)keys.add(dy>0?'s':'w');}
  function releaseStick(){stickPointer=null;knob.style.transform='';for(const k of ['w','a','s','d'])keys.delete(k);}
  stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);
  $('touch-fire').addEventListener('pointerdown',e=>{e.preventDefault();mouse.x=vw/2+40;mouse.y=vh/2;fire();});
  $('touch-interact').addEventListener('pointerdown',e=>{e.preventDefault();interact();});
  setMission();updateVitals();
})();

