(async()=>{const b=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});const p=await b.newPage({viewport:{width:1280,height:800}});const errors=[];p.on('pageerror',e=>errors.push(e.message));p.on('console',m=>{if(m.type()==='error')errors.push(m.text())});await p.goto('http://localhost:3002');await p.waitForTimeout(300);const css=await p.evaluate(()=>({rules:document.styleSheets[0].cssRules.length,coverPosition:getComputedStyle(document.querySelector('.screen-cover')).position}));await p.locator('#start-button').click();await p.keyboard.down('d');await p.waitForTimeout(720);await p.keyboard.up('d');await p.keyboard.press('e');await p.waitForTimeout(150);const dialogue=await p.evaluate(()=>({visible:!document.querySelector('#dialogue').classList.contains('hidden'),text:document.querySelector('#dialogue-text').innerText,interaction:!document.querySelector('#interaction').classList.contains('hidden')}));if(dialogue.visible){await p.keyboard.press('e');await p.keyboard.press('e')}await p.waitForTimeout(200);await p.screenshot({path:'/tmp/opencode/after-the-tide-validated.png'});console.log(JSON.stringify({css,dialogue,errors},null,2));await b.close();if(errors.length)process.exit(2)})().catch(e=>{console.error(e);process.exit(1)});
